scripts.事件21_4.txt:
	Say("杨影枫：胡神医，她的毒可否能解？", 8);
	Say("胡神医：“七星草”的毒性虽然霸道，又如何能难倒我胡某！难道我这“神医”二字是浪得虚名吗？", 45);
	Say("杨影枫：我知道神医的医术天下无人能及，所以才长途跋涉来到这里，恳情胡神医为这位姑娘治病！", 8);
	Say("胡神医：救人简单，既然你知道来这里找我，就应该知道我的规矩。", 45);
	Say("杨影枫：神医是不是要什么宝物？", 2);
	Say("胡神医：不错。在<color=Red>药王谷<color=Black>的<color=Red>西南方<color=Black>不远，有一个门派，叫做<color=Red>霹雳堂<color=Black>。该派以制造极其厉害的炸药和火器而称霸武林。霹雳堂有一样镇派之宝，名叫<color=Red>雷震子<color=Black>，平时收藏在霹雳堂的<color=Red>听雷阁<color=Black>里面，防护严密。老夫想了好久，一直弄不到手。你若能帮老夫弄来，这位姑娘的毒，老夫立刻解了。", 45);
	Say("杨影枫：雷震子？", 4);
	Say("胡神医：对。霹雳堂平时作恶多端，凭着他们的独门火器，到处杀人抢劫，干的都是没本钱的买卖，因此也聚集了一大批武林高手。那里是他们的总坛，多少武林中人想闯霹雳堂，都是进得去出不来。看你年纪轻轻，就自己斟酌斟酌吧，丢了性命，可莫怪老夫。", 45);

	Choose("你要去盗雷震子吗？", "去。", "不去。", $SelectVal63);
	// 去
	If ($SelectVal63 == 0) @Label1;
	// 不去
	If ($SelectVal63 == 1) @Label2;
@Label1:
	Talk(2840, 2850);
	Say("杨影枫：在下功力尚浅，冒险闯霹雳堂实是九死一生。倘若在下真的回不来，难道你也眼睁睁看她死？",2);
	Say("胡神医：不错！倘若我没有拿到所要的宝物，她就是在我面前死一千次，我也不会救她一次。多说无益，你还不去快拿雷震子？若误了救她的时辰，哼哼……",	45);
	Say("杨影枫：好，在下一定拿到雷震子来相见！", 2);
	Say("胡神医：那你听仔细了，那<color=Red>雷震子<color=Black>放在<color=Red>霹雳堂听雷阁<color=Black>。",	45);
	Add($SenseVal, 40);
	Goto @Label3;
@Label2:
	Say("杨影枫：（霹雳堂那么难闯，我去恐怕也是九死一生，不仅救不了紫轩，还枉送了性命……）", 7);
	Say("杨影枫：你悬壶济世，号称神医，却为什么没有一点慈悲心肠！", 6);
	Say("胡神医：哼！给不给宝由你，救不救人由我，这是我的规矩，你自己看着办。这位姑娘中毒不轻，时间耽搁久了就很难治了，到时你可别后悔！", 45);
	Say("杨影枫：你！（紫轩她不能死，如果没有了她，我……罢罢罢，为了救紫轩，我就勉为其难吧！）好，你不必再出言讥讽，在下一定拿到雷震子就是！", 6);
	Say("胡神医：那你记住了，雷震子放在霹雳堂听雷阁。", 45);
	Add($SenseVal, -40);
	Goto @Label3;
@Label3:	
	Sleep(500);
	PlayerGoto(35, 76);
	SetPlayerDir(4);
	Talk(2896, 2896);
    AddToMemo(2894);
	Assign($Event, 210);
	Return;

scripts.蔷薇对话.txt:
	If ($Event == $2030) @L2030;
	Return;
	
@L2030:
	Say("杨影枫：薇儿，胡神医一定有办法救你。",2);
	Say("蔷薇：嗯……影枫哥……",30);
	Return;

scripts.胡神医对话.txt:
	If ($Event == 2030) @L2030;
	If ($Event == 220) @Label;
	
	GetRandNum($hushenyiTalk,0,1);

	If ($hushenyiTalk == 0) @Talk1;
	If ($hushenyiTalk == 1) @Talk2;
	Goto @end;
@Talk1:
	Talk(2893, 2893);
	Return;
@Talk2:
	Talk(2897, 2897);
	Return;
	
@Label:	
	RunScript("Trap02.txt");
	Return;
	
@L2030:
	Say("胡神医：噫？这不是杨老弟吗？怎么又有空儿到我这里来作客了。",45);
	Say("杨影枫：胡神医，我是来找你救人的。",2);
	Say("胡神医：哈哈，果然是无事不登三宝殿，又要我救哪位美女呀？",45);
	Say("杨影枫：胡神医，就是我身后这位姑娘，她是武林盟主孟知秋的女儿。",2);
	Say("胡神医：哈哈，你真是艳福不浅哪，连武林盟主的女儿也给你弄到手了。",45);
	Say("杨影枫：胡神医，她中了“黑煞瘟神”卜风的穿肠雪蛛之毒，今天已经是第五天了。",8);
	Say("胡神医：穿肠雪蛛毒……这种毒药来自西域，相传是用西域穿肠草加上西域雪蛛之毒配制而成。",45);
	Say("杨影枫：这么说你可以解穿肠雪蛛之毒了？",8);
	Say("胡神医：这两种毒性本来相互克制，但如果同时使用，在一定时间之后，中毒者就会被其中剂量较多的一种毒杀死。",45);
	Say("杨影枫：那如何解法？",8);
	Say("胡神医：据我所知，只有用另外一种毒才能解。",45);
	Say("杨影枫：那什么地方可以找到穿肠草和雪蛛？",8);
	Say("胡神医：……先让我看一看这位姑娘是否真的中了这种毒。",45);

	PlayerGoto(35,76);
	SetNpcKind("蔷薇",1);
	NpcGoto("蔷薇",35,77);
	Watch("蔷薇","胡神医",0);
	FadeOut();
	Say("……良久……");
	FadeIn();

	Watch("杨影枫","胡神医",0);
	Watch("蔷薇","胡神医",1);
	Say("胡神医：没错，她的确中了穿肠雪蛛毒，而且再不出五日，雪蛛之毒就会发作，到时全身会逐渐溃烂……",45);
	Say("蔷薇：……不要再说了……",32);
	Say("杨影枫：那你快救救她吧……",8);
	Say("胡神医：……杨少侠……请恕胡某无能为力。",45);
	Say("杨影枫：什么……为什么？",6);
	Say("胡神医：穿肠草和雪蛛远在西域，中原罕有。就算你能取得来，也为时已晚了。",45);
	Say("杨影枫：不！我不信！",5);
	Say("胡神医：……杨少侠……老朽句句实言，请勿见怪。",45);
	Say("杨影枫：不……你骗我……",6);

	Watch("蔷薇","杨影枫",0);
	Say("蔷薇：影枫哥……我们回去吧……",32);
	Say("杨影枫：薇儿……",5);
	Sleep(1000);
	Say("杨影枫：也好……我们先回悲魔山庄吧",2);
	Say("蔷薇：嗯……影枫哥……",29);
	Say("胡神医：……杨少侠……慢着……",45);
	Say("杨影枫：什么事？",4);
	Say("胡神医：杨少侠，我这里有十颗“天心锁命丹”，待她毒发之时可以暂时镇住毒性，每日服一粒，可延她十日性命。",45);
	Say("杨影枫：……多谢胡神医……",5);
	Say("胡神医：何必言谢……可惜我不能医好她……",45);
	Say("杨影枫：薇儿，我们走吧……",5);
	Say("胡神医：恕不远送……",45);

	SetNpcKind("蔷薇",3);
	PlayerGotoEx(32,85);
	Sleep(1000);
	FadeOut();
	LoadMap("map_030_悲魔山庄.map");
	LoadNpc("map030_1.npc");
	LoadObj("map030_obj.obj");
	SetPlayerPos(9, 225);
	SetPlayerDir(5);
	Say("经过数日行程，二人又回到了悲魔山庄，但蔷薇已经一天比一天憔悴了。");
	DelNpc("纳兰真");
	AddNpc("纳兰真.ini",19,200,1);
	SetNpcScript("纳兰真","真儿对话.txt");
	ClearBody();
	FadeIn();
	SetMapTrap(1,"");
	SetMapTrap(5,"");
	SetMapTrap(6,"");
	SetMapTrap(13,"");
	Assign($Event, 2031);
	RunScript("药王谷归来.txt");
	Return;

