traps.Trap02.txt:
	If ($Event <> 220) @end;

	DelNpc("苍鹰");
	PlayerGoto(35, 77);
	SetPlayerDir(5);
	SetNpcDir("胡神医",1);
	//Talk(3010, 3020);
	Say("杨影枫：大夫，我拿到<color=Red>雷震子<color=Black>了，请查收。", 2);
	Say("胡神医：哈哈，果然是<color=Red>雷震子<color=Black>，霹雳堂的独门暗器！哈哈哈……",	45);
	DelGoods("Goods-e02-雷震子.ini");
	//Talk(3030, 3040);
