	SetNpcPos("胡神医", 36, 76);
	SetNpcDir("胡神医",3);
	FadeIn();

	SetNpcActionFile("紫轩", 0, "npc010_st.asf");
	SetNpcActionFile("紫轩", 1, "npc010_pst.asf");
	NpcSpecialAction("紫轩", "mpc050.asf");
	Sleep(3000);

	FadeOut();
	SetNpcPos("紫轩", 35, 76);
	SetNpcDir("紫轩", 7);
	SetNpcDir("胡神医",1);
	FadeIn();
