	Say("紫轩：杨大哥……", 18);
	Say("杨影枫：紫轩！你醒了！你总算醒了，真是太好了！", 2);
	Say("紫轩：杨大哥，我怎么会在这里？我记得我在芭蕉小筑等你，突然来了一群恶人，把芭蕉小筑烧了，然后……", 17);
	Say("杨影枫：这里是<color=Red>药王谷<color=Black>，你中了那群恶人的毒，我带你来此医治。多亏这位神医搭救，要不然我可真不知道怎么办好！", 2);
	SetNpcDir("紫轩",6);
	Say("紫轩：多谢神医救命之恩。", 16);
	Say("胡神医：姑娘，我救你可不是白救的，是收了报酬的，所以你不用谢我。倒是你这位情郎，孤身一人闯入霹雳堂，取来雷震子，要不然你现在大概已经在地下了，你该谢他才对。", 45);
	SetNpcDir("紫轩",7);
	Sleep(300);
	Say("紫轩：霹雳堂？就是以火器横行江湖的江南霹雳堂？", 18);
	Say("胡神医：不错。", 45);
	Say("紫轩：杨大哥，你为了救我，竟连自己的性命都不顾了！你竟然只身去闯那霹雳堂，那霹雳堂的人可都是杀人不眨眼的魔王啊！杨大哥，你对我实在是太好了！呜呜……", 20);
	Say("杨影枫：紫轩，不要哭了，我现在不是好好的吗？乖，不哭了。", 3);
	Say("紫轩：杨大哥，我对不起你……", 20);
	Say("杨影枫：傻瓜，我们之间还讲什么对不对得起，只要你没事就好。我们回去吧，大哥以后再也不离开你了！", 2);
	SetPlayerDir(5);
	Say("杨影枫：神医，多谢救命之恩。我们就此告辞。", 2);
	Say("胡神医：不送。", 45);
	Assign($Event, 230);
	FadeOut();
	StopMusic();
	FullLife();
	FullThew();
	FullMana();
	Say("几天以后，杨影枫和紫轩回到了清平乡。");
	ClearBody();
	SaveObj();
	LoadMap("map_022_清平乡.map");
	LoadNpc("qingpingxiang.npc");
	LoadObj("map022_obj.obj");
	PlayMusic("mc007.mp3");
